!function(e){e(window).on("elementor/frontend/init",function(){let e,t=elementorModules.frontend.handlers.Base;e=t.extend({bindEvents:function(){this.run()},getDefaultSettings:function(){return{allowHTML:!0}},settings:function(e){return this.getElementSettings("reading_timer_"+e)},calculateReadingTime:function(e){let t=this.settings("avg_words_per_minute"),n=e.split(/\s+/).filter(function(e){return""!==e}).length,i=(t&&parseInt(t.size,10)>0?parseInt(t.size,10):0)||200,s=Math.floor(n/i),o=Math.floor(n%i/(i/60)),r=this.settings("minute_text")?this.settings("minute_text"):"min read",d=this.settings("seconds_text")?this.settings("seconds_text"):"sec read";return n>=i?`${s} ${r}`:`${o} ${d}`},run:function(){const e=this.$element.find(".bdt-reading-timer"),t=this.settings("content_id");let n=this.settings("minute_text")?this.settings("minute_text"):"min read";if(Boolean(elementorFrontend.isEditMode()))e.append(document.createTextNode("2 "+String(n)));else if(t){const n=document.getElementById(String(t)),i=n?n.textContent:"",s=this.calculateReadingTime(i);e.append(document.createTextNode(String(s)))}}}),elementorFrontend.hooks.addAction("frontend/element_ready/bdt-reading-timer.default",function(t){elementorFrontend.elementsHandler.addHandler(e,{$element:t})})})}(jQuery,window.elementorFrontend);